$Run='C:\Users\aaron\Desktop\URAP\artifacts\detached_tvd_detector_select_v134';$pidValue=[int](Get-Content (Join-Path $Run 'pid.txt') -Raw);$p=Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue" -ErrorAction SilentlyContinue;$meta=Get-Content (Join-Path $Run 'start_meta.json') -Raw|ConvertFrom-Json;$prog=if(Test-Path (Join-Path $Run 'progress.json')){Get-Content (Join-Path $Run 'progress.json') -Raw|ConvertFrom-Json};"STATUS=$(if($p){'RUNNING'}else{'NOT RUNNING'})";if($prog){"DONE_TOTAL=$($prog.done)/$($prog.total) STAGE=$($prog.stage) WEIGHT=$($prog.weight) UPDATED=$($prog.updated)"};"PID=$pidValue START=$($meta.start_time)";if(Test-Path (Join-Path $Run 'child_pid.txt')){$c=[int](Get-Content (Join-Path $Run 'child_pid.txt') -Raw);$cp=Get-CimInstance Win32_Process -Filter "ProcessId=$c" -ErrorAction SilentlyContinue;"CHILD_PID=$c CHILD_STATUS=$(if($cp){'RUNNING'}else{'NOT RUNNING'})"};$logs=Get-ChildItem $Run -Filter 'stderr_epoch*.log' -File|Sort LastWriteTime -Descending;if($logs){"LAST_OUTPUT=$($logs[0].LastWriteTime.ToString('o')) FILE=$($logs[0].FullName)";Get-Content $logs[0].FullName -Tail 12};"GPU=$(& nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total --format=csv,noheader,nounits)";Get-Content $meta.stderr -Tail 10 -ErrorAction SilentlyContinue
